#define _GNU_SOURCE
#include <assert.h>
#include <sched.h>
#include <signal.h>
#include <stdio.h>
#include <sys/wait.h>
#include <unistd.h>

/* CPU 0 receives the PIC interrupts generated by the active device load. */
int main(void)
{
	cpu_set_t cpus;
	CPU_ZERO(&cpus);
	CPU_SET(0, &cpus);
	assert(sched_setaffinity(0, sizeof(cpus), &cpus) == 0);
	alarm(120);
	for (unsigned i = 0; i < 2000; i++) {
		pid_t child = fork();
		assert(child >= 0);
		if (!child) {
			for (;;)
				__asm__ volatile("pause");
		}
		usleep((i % 10 + 1) * 100);
		assert(kill(child, SIGKILL) == 0);
		int status;
		assert(waitpid(child, &status, 0) == child);
		assert(WIFSIGNALED(status) && WTERMSIG(status) == SIGKILL);
	}
	puts("PIC CPU task termination stress passed: 2000 children");
	return 0;
}
